import json,yaml
g=json.load(open("$R/backend/target/openapi.json"))
c=yaml.safe_load(open("$R/specs/002-us-tags-backend/contracts/openapi.yaml"))
def ops(d):
  r={}
  for p,m in d.get('paths',{}).items():
    for k,v in m.items():
      if isinstance(v,dict) and 'operationId' in v: r[v['operationId']]=(p,k,v)
  return r
go,co=ops(g),ops(c)
for op in ['listTasks','addTaskTags','removeTaskTag']:
  print("==",op); print("C:",json.dumps(co.get(op,(None,None,{}))[:2]), json.dumps(co.get(op,[0,0,{}])[2].get('parameters'))[:600])
  print("G:",json.dumps(go.get(op,(None,None,{}))[:2]), json.dumps(go.get(op,[0,0,{}])[2].get('parameters'))[:600])
  for s in ['requestBody','responses']:
    print(" C",s,json.dumps(co.get(op,[0,0,{}])[2].get(s))[:500]); print(" G",s,json.dumps(go.get(op,[0,0,{}])[2].get(s))[:500])
cs,gs=c['components']['schemas'],g['components']['schemas']
print("C TaskTags",json.dumps(cs.get('TaskTags'))); print("G TaskTags",json.dumps(gs.get('TaskTags')))
print("C Task.tags",json.dumps(cs['Task']['properties'].get('tags')),'tags' in cs['Task'].get('required',[]))
print("G Task.tags",json.dumps(gs.get('Task',{}).get('properties',{}).get('tags')),'tags' in gs.get('Task',{}).get('required',[]))
print(list(gs))
EOF
